def firstUniqueEven(nums):
    # Count how many times each value appears
    count = {}
    for x in nums:
        count[x] = count.get(x, 0) + 1
    # Scan left to right, first even value with count exactly 1 wins
    for x in nums:
        if x % 2 == 0 and count[x] == 1:
            return x
    return -1
